import Foundation

/// 記録しない内容の判定（docs/specs/filtering.md）。迷ったら記録しない側に倒す。
public enum ContentFilter {
    public enum Decision: Equatable {
        case record
        case skip(Reason)
    }

    /// ログに出してよいのはこの理由だけ。内容は出さない。
    public enum Reason: String {
        case empty
        case tooLarge
        case marker
        case excludedApp
        case sensitivePattern
    }

    public static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
    ]

    public static let excludedBundleIDs: Set<String> = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
        "com.apple.keychainaccess",
        "com.apple.Passwords",
    ]

    static let sensitivePatterns: [NSRegularExpression] = [
        #"-----BEGIN [A-Z ]*PRIVATE KEY-----"#,
        #"gh[pousr]_[A-Za-z0-9]{36,}"#,
        #"github_pat_[A-Za-z0-9_]{22,}"#,
        #"\b(AKIA|ASIA)[0-9A-Z]{16}\b"#,
        #"xox[abprs]-[A-Za-z0-9-]{10,}"#,
        #"sk-ant-[A-Za-z0-9_-]{20,}"#,
        #"sk-[A-Za-z0-9_-]{20,}"#,
        #"AIza[0-9A-Za-z_-]{35}"#,
        #"eyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}"#,
    ].map { try! NSRegularExpression(pattern: $0) }

    public static func evaluate(text: String, pasteboardTypes: [String], frontmostBundleID: String?) -> Decision {
        if !concealedTypes.isDisjoint(with: pasteboardTypes) {
            return .skip(.marker)
        }
        if let frontmostBundleID, excludedBundleIDs.contains(frontmostBundleID) {
            return .skip(.excludedApp)
        }
        if text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return .skip(.empty)
        }
        if text.utf8.count > Config.maxTextBytes {
            return .skip(.tooLarge)
        }
        if containsSensitivePattern(text) {
            return .skip(.sensitivePattern)
        }
        return .record
    }

    public static func containsSensitivePattern(_ text: String) -> Bool {
        let range = NSRange(text.startIndex..., in: text)
        return sensitivePatterns.contains { $0.firstMatch(in: text, range: range) != nil }
    }
}
